import{z as E,x as s,o as e,c as A,q as p,j as t,D as l,d as n,s as o,S as r}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"多语言 α 采样","description":"","frontmatter":{"title":"多语言 α 采样","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/multilingual-alpha-sampling.md","filePath":"llm/multilingual-alpha-sampling.md","lastUpdated":1791413859000}'),h={name:"llm/multilingual-alpha-sampling.md"};function d(D,a,_,m,B,u){const i=s("Mermaid");return e(),A("div",null,[a[2]||(a[2]=p('<h1 id="多语言-α-采样" tabindex="-1">多语言 α 采样 <a class="header-anchor" href="#多语言-α-采样" aria-label="Permalink to &quot;多语言 α 采样&quot;">​</a></h1><div class="epigraph"><p>按语种频次的 $\\alpha$ 次幂抽样，低资源语言被抬起来，高资源语言仍占大头；$\\alpha=1$ 是自然分布，$\\alpha=0$ 是语种均匀。</p><footer>—— Conneau 与 Lample，XLM；Conneau 等，XLM-R</footer></div><p><a href="/llm/influence-data-selection">上一课</a>用梯度给文档打分，贵，且假定探针已定。多语言预训练常常连「主探针」都还没有，却必须先决定 100 种语言各吃多少 token。本课不重讲影响函数。缺口是一个只依赖语种频次的便宜旋钮：XLM / XLM-R 的 \\(\\alpha\\)-sampling。它补的是支撑与公平，不是桶内质量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/web-clean-dedup">网页清洗</a> 之后，英语仍可能占 web 的一大半。按自然 token 分布训，低资源语言的子词本就更碎（fertility 课），再叠加更少的句子，模型在那些语言上接近没训。按语种均匀采，英语能力会掉，而且低资源语种的重复率飙升，变成过拟合那一小摊爬取。需要在 \\(p_i^{\\alpha}\\) 上插值：设语种 \\(i\\) 的自然份额为 \\(p_i\\)，抽样概率 \\(q_i\\propto p_i^{\\alpha}/\\sum_j p_j^{\\alpha}\\)。</p><p>Conneau 等人在 XLM 与 XLM-R 里把 \\(\\alpha\\) 当成多语言 MLM 的标准旋钮。预训练自回归模型同样能用，只是会计从「句子」换成「token」，并要与 fertility 一起读：\\(\\alpha\\) 补偿的是语种出现次数，不是切分倍率。</p><p><span class="marginnote">\\(\\alpha\\) 就是一个「抬尾旋钮」：\\(\\alpha=1\\) 是完全照自然分布抽样，\\(\\alpha=0\\) 是完全无视自然分布、语种平均分，中间值是在两者之间插值。XLM-R 取 0.3，意思是「往均匀方向大幅推，但保留一点头部倾斜」。</span></p><h3 id="不是质量分" tabindex="-1">\\(\\alpha\\) 不是质量分 <a class="header-anchor" href="#不是质量分" aria-label="Permalink to &quot;$\\alpha$ 不是质量分&quot;">​</a></h3><p>低资源语种的爬取往往更噪。提高 \\(q_i\\) 会多喂噪声，除非该语种先经过同样严格的过滤。α 采样在干净的语种边际上操作；脏数据应在进入 \\(p_i\\) 统计之前杀掉，否则 \\(p_i\\) 本身被垃圾撑大。</p><p><span class="marginnote">语言识别错误会制造幽灵语种或把方言并进大语种。\\(p_i\\) 应在识别之后、去重之后统计，并定期抽检。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在去重后的语料上估计 \\(p_i\\)（按 token 或按字符；选定后不得混用）。选 \\(\\alpha\\in[0,1]\\)：XLM-R 一类常用 \\(0.3\\) 或 \\(0.5\\) 量级，使尾部语种可见又不过分重复。加载器按 \\(q_i\\) 做带权抽样；对极小语种设重复上限与 epoch 内无放回，防止同一页每个 epoch 出现几十次。与领域桶相乘：先语种 \\(q\\)，再在语种内按来源 \\(w\\)，或反过来做成层次——必须写清顺序，两种顺序给出不同的联合分布。</p>',12)),(e(),t(r,null,{default:l(()=>[o(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20EN%5B%22%E8%8B%B1%E8%AF%AD%20p%3D0.5%22%5D%20--%3E%20C%5B%22q%20%E6%AD%A3%E6%AF%94%E4%BA%8E%20p%20%E7%9A%84%20%CE%B1%20%E6%AC%A1%E5%B9%82%22%5D%0A%20%20ZH%5B%22%E4%B8%AD%E6%96%87%20p%3D0.05%22%5D%20--%3E%20C%0A%20%20SW%5B%22%E6%96%AF%E7%93%A6%E5%B8%8C%E9%87%8C%E8%AF%AD%20p%3D0.001%22%5D%20--%3E%20C%0A%20%20C%20--%3E%20A1%5B%22%CE%B1%3D1%EF%BC%9A%E8%87%AA%E7%84%B6%E5%88%86%E5%B8%83%22%5D%0A%20%20C%20--%3E%20A2%5B%22%CE%B1%3D0.3%EF%BC%9AXLM-R%20%E5%B8%B8%E7%94%A8%22%5D%0A%20%20C%20--%3E%20A3%5B%22%CE%B1%3D0%EF%BC%9A%E8%AF%AD%E7%A7%8D%E5%9D%87%E5%8C%80%22%5D%0A%20%20A1%20--%3E%20O1%5B%22q%20%3D%2090.7%25%20%2F%209.1%25%20%2F%200.2%25%22%5D%0A%20%20A2%20--%3E%20O2%5B%22q%20%3D%2060.4%25%20%2F%2030.3%25%20%2F%209.4%25%22%5D%0A%20%20A3%20--%3E%20O3%5B%22q%20%3D%2033.3%25%20%2F%2033.3%25%20%2F%2033.3%25%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=p('<p><span class="marginnote">数字实例：设英语 \\(p=0.5\\)、斯瓦希里语 \\(p=0.001\\)。\\(\\alpha=1\\) 时斯瓦希里语只能抽到约 \\(0.2\\%\\)；把 \\(\\alpha\\) 降到 \\(0.3\\)，它升到约 \\(9.4\\%\\)，英语则从 \\(90.7\\%\\) 降到 \\(60.4\\%\\)——尾部语种被抬了约 50 倍，而头部语言的能力池子还在。</span></p><p>把 α 与 <a href="/llm/doremi">DoReMi</a> 一起用时，不要让 DRO 再去「发现」语种权重，除非桶的定义里没有语种轴。一轴一方法：语种用 α，来源用 DRO 或人工。RegMix 的设计点也可以把 α 当成一个标量自变量扫。</p><h3 id="与词表的耦合" tabindex="-1">与词表的耦合 <a class="header-anchor" href="#与词表的耦合" aria-label="Permalink to &quot;与词表的耦合&quot;">​</a></h3><p>α 抬起的语种若词表覆盖差，抬起来的是更长的字节回退序列，有效语义更少。扩表应先于把 α 降得很低。fertility 报表是验收：过采样后，该语种的有效字符预算是否真的上升。</p><p><span class="marginnote">评测集语种分布若与 \\(q\\) 一致，分数会好看；产品用户若更偏英语，应对产品分布单独报。α 是训练测度，不是承诺公平测树。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(p_i^{\\alpha}\\) 在对数单纯形上把质量从头部推向尾部，\\(\\alpha\\) 越小越均匀。重复的代价是：尾部语种的独特文档少，模型记忆那些页。Lee 等人对重复与记忆的结论在语种维上同样成立。因此 α 必须与去重、重复上限一起设，而不是单独调到验证 perplexity 最低——最低往往是多喂英语。</p><p><span class="marginnote">初学者容易以为把 \\(\\alpha\\) 设成 0 最「公平」，实际上低资源语种的独特文档远撑不满均匀份额：同一批网页每个 epoch 反复出现，模型背下来的是那几页爬取，而不是学会了这门语言。所以 α 要与重复上限一起设，不能拧到头。</span></p>',8)),(e(),t(r,null,{default:l(()=>[o(i,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%8E%BB%E9%87%8D%E5%90%8E%E8%AF%AD%E7%A7%8D%E4%BB%BD%E9%A2%9D%20p%22%5D%20--%3E%20A%5B%22q%20%E6%AD%A3%E6%AF%94%E4%BA%8E%20p%20%E7%9A%84%20%CE%B1%20%E6%AC%A1%E5%B9%82%22%5D%0A%20%20A%20--%3E%20S%5B%22%E5%B8%A6%E6%9D%83%E5%8A%A0%E8%BD%BD%22%5D%0A%20%20W%5B%22%E9%A2%86%E5%9F%9F%E6%A1%B6%E6%9D%83%E9%87%8D%22%5D%20--%3E%20S%0A%20%20S%20--%3E%20LIM%5B%22%E5%B0%BE%E9%83%A8%E8%AF%AD%E7%A7%8D%E9%87%8D%E5%A4%8D%E4%B8%8A%E9%99%90%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=p('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>α 采样不管代码仓库结构、不管长文档、不管指令格式。那些是随后几课的排布与目标问题。它也不选「哪一篇中文更好」——那是影响函数或质量模型。把 α 调到 0 当作政治正确，会得到一轮均匀的过拟合。下一课进入代码：单位从语种变成仓库，抽样要保持文件间的依赖，而不是把文件当独立语言页。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本课不重讲梯度选文档；只补语种频次的幂次抽样。</li><li>\\(q_i\\propto p_i^{\\alpha}\\) 在自然分布与均匀之间插值；与领域 \\(w\\) 层次相乘，顺序要写清。</li><li>先过滤再估计 \\(p_i\\)；尾部设重复上限。</li><li>词表覆盖不足时，降 α 只会多喂碎片。</li><li>出处：Conneau &amp; Lample, XLM, 2019；Conneau et al., XLM-R, 2020；重复与记忆对照 Lee et al., 2022。</li></ul>',4))])}const f=E(h,[["render",d]]);export{C as __pageData,f as default};
